// Convierte la foto recibida a base64 para Claude
const items = [];
for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) {
    throw new Error('No se recibió ninguna foto. Envía la imagen en el campo "foto".');
  }
  const key = binaryKeys[0];
  const binary = item.binary[key];
  const base64 = binary.data; // n8n ya guarda base64 en .data
  let mediaType = binary.mimeType || 'image/jpeg';
  if (!['image/jpeg','image/png','image/webp','image/gif'].includes(mediaType)) {
    mediaType = 'image/jpeg';
  }
  // Modo: ?mode=both|stories|tiktok  (default both)
  const mode = ($json.query && $json.query.mode) || $json.mode || 'both';
  items.push({ json: { base64, mediaType, mode, filename: binary.fileName || 'foto' } });
}
return items;

