// Extrae y parsea el JSON que devuelve Claude
const out = [];
for (const item of $input.all()) {
  const text = item.json.content?.[0]?.text || '';
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}') + 1;
  let plan;
  try {
    plan = JSON.parse(text.slice(start, end));
  } catch (e) {
    plan = { error: 'No se pudo parsear', raw: text };
  }
  out.push({ json: plan });
}
return out;
